/*
 * Sidebar LP player
 * - The disc spins (10 s per turn) only while music plays; the clear case stays still.
 * - Tracks come from the /music/ folder (list is generated by Jekyll into #lp-tracks).
 *
 * Image layers (images/player/):
 *   case.webp  static case, transparent background, disc area cut out (centre hole kept)
 *   disc.webp  disc print with the case's lighting removed  -> this layer rotates
 *   light.png  case lighting/tint over the disc (value/255*2 = multiplier), static
 *   glare.png  case ridge highlights over the disc (value-128 = offset), static
 *   mask.png   disc alpha (ring between centre hole and rim)
 */
(function () {
  'use strict';

  var root = document.getElementById('lp-player');
  if (!root) return;

  // iPhone / iPad (iPadOS reports itself as a Mac with touch)
  var IOS = /iP(hone|ad|od)/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  if (IOS) root.classList.add('is-ios');

  var SECONDS_PER_TURN = 10;   // slow LP-like spin
  var SPIN_EASE = 0.7;         // seconds to spin up / slow down

  var canvas = root.querySelector('.lp-canvas');
  var ctx = canvas.getContext('2d');
  var toggleBtn = root.querySelector('.lp-toggle');
  var prevBtn = root.querySelector('.lp-prev');
  var nextBtn = root.querySelector('.lp-next');
  var titleEl = root.querySelector('.lp-title span');
  var audio = root.querySelector('audio');

  var W = +root.getAttribute('data-w'), H = +root.getAttribute('data-h');
  var DX = +root.getAttribute('data-dx'), DY = +root.getAttribute('data-dy');
  var DS = +root.getAttribute('data-ds');
  var base = root.getAttribute('data-asset');

  // ---------- playlist ----------
  var tracks = [];
  try { tracks = JSON.parse(document.getElementById('lp-tracks').textContent) || []; } catch (e) { tracks = []; }
  tracks.sort(function (a, b) { return a.src.localeCompare(b.src, undefined, { numeric: true }); });
  var N = tracks.length;
  var rockWords = [];
  try { rockWords = JSON.parse(document.getElementById('lp-rock').textContent) || []; } catch (e) {}
  tracks.forEach(function (t) {
    var name = (t.title || '').toLowerCase();
    t.rock = rockWords.some(function (w) { return w && name.indexOf(String(w).toLowerCase()) >= 0; });
  });
  var index = 0;

  var shuffleBtn = root.querySelector('.lp-shuffle');
  var repeatBtn = root.querySelector('.lp-repeat');
  var listBtn = root.querySelector('.lp-list-btn');
  var listEl = root.querySelector('.lp-list');

  // play order: folder order, or a shuffled permutation when shuffle is on
  var shuffle = false, repeatOne = false;
  var order = [], pos = 0;

  function store(key, val) { try { localStorage.setItem(key, val ? '1' : '0'); } catch (e) {} }
  function stored(key) { try { return localStorage.getItem(key) === '1'; } catch (e) { return false; } }

  function shuffled(arr) {
    for (var i = arr.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1)), t = arr[i]; arr[i] = arr[j]; arr[j] = t;
    }
    return arr;
  }
  // Rebuild the play order so that the current track sits at `pos`.
  function rebuildOrder() {
    var all = [];
    for (var i = 0; i < N; i++) all.push(i);
    if (shuffle) {
      var rest = shuffled(all.filter(function (k) { return k !== index; }));
      order = [index].concat(rest);
      pos = 0;
    } else {
      order = all;
      pos = index;
    }
  }

  // Encode each path segment so spaces, Korean, emoji, '#', '?' etc. in file names work.
  function trackUrl(src) {
    return src.split('/').map(function (seg) {
      try { seg = decodeURIComponent(seg); } catch (e) {}
      return encodeURIComponent(seg);
    }).join('/');
  }

  function prettyTitle(t) { return t.title.replace(/[_]+/g, ' ').trim(); }

  function loadTrack(i) {
    index = (i + N) % N;
    audio.src = trackUrl(tracks[index].src);
    audio.loop = repeatOne;
    titleEl.textContent = prettyTitle(tracks[index]);
    titleEl.parentNode.title = titleEl.textContent;
    updateMarquee();
    markActive();
  }

  // While playing, the title runs like a train: it rolls in from the right at a steady pace,
  // stops dead for a moment (centred, or left-aligned if it is longer than the box),
  // then rolls off to the left at the same pace and the next run comes in.
  var TRAIN_SPEED = 28;     // px per second (same pace as the original ticker)
  var TRAIN_STOP = 1.8;     // seconds standing at the platform
  var ticker = null;
  var reduceMotionTitle = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function stopMarquee() {
    if (ticker) { ticker.cancel(); ticker = null; }
  }
  function updateMarquee() {
    stopMarquee();
    if (!root.classList.contains('is-playing') || reduceMotionTitle || !titleEl.animate) return;
    var boxW = titleEl.parentNode.clientWidth, textW = titleEl.offsetWidth;
    if (!boxW || !textW) return;
    var stopX = textW <= boxW ? (boxW - textW) / 2 : 0;
    var tIn = (boxW - stopX) / TRAIN_SPEED;
    var tOut = (stopX + textW) / TRAIN_SPEED;
    var total = tIn + TRAIN_STOP + tOut;
    ticker = titleEl.animate([
      { transform: 'translateX(' + boxW + 'px)', offset: 0 },                    // arriving
      { transform: 'translateX(' + stopX + 'px)', offset: tIn / total },
      { transform: 'translateX(' + stopX + 'px)', offset: (tIn + TRAIN_STOP) / total },  // stopped, then departing
      { transform: 'translateX(' + (-textW) + 'px)', offset: 1 }
    ], { duration: total * 1000, iterations: Infinity, easing: 'linear' });
  }

  // ---------- track list panel ----------
  function buildList() {
    var frag = document.createDocumentFragment();
    tracks.forEach(function (t, i) {
      var li = document.createElement('li');
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'lp-list-item';
      b.setAttribute('data-i', i);
      var num = document.createElement('span');
      num.className = 'lp-list-num';
      num.textContent = i + 1;
      var name = document.createElement('span');
      name.className = 'lp-list-name';
      name.textContent = prettyTitle(t);
      b.appendChild(num); b.appendChild(name);
      li.appendChild(b);
      frag.appendChild(li);
    });
    listEl.appendChild(frag);
  }
  function markActive() {
    var items = listEl.querySelectorAll('.lp-list-item');
    for (var i = 0; i < items.length; i++) {
      var on = i === index;
      items[i].classList.toggle('is-current', on);
      if (on) items[i].setAttribute('aria-current', 'true'); else items[i].removeAttribute('aria-current');
    }
  }
  function scrollActiveIntoView() {
    var cur = listEl.querySelector('.is-current');
    if (cur) listEl.scrollTop = cur.parentNode.offsetTop - listEl.clientHeight / 2 + cur.offsetHeight / 2;
  }
  listBtn.addEventListener('click', function () {
    var open = listEl.hidden;
    listEl.hidden = !open;
    listBtn.classList.toggle('is-on', open);
    listBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
    if (open) scrollActiveIntoView();
  });
  listEl.addEventListener('click', function (e) {
    var b = e.target.closest('.lp-list-item');
    if (!b) return;
    var i = +b.getAttribute('data-i');
    if (i === index && !audio.paused) return;          // already playing this one
    if (i !== index) { loadTrack(i); rebuildOrder(); }
    audio.play().catch(function () {});
  });

  // ---------- shuffle / repeat-one ----------
  function syncModeButtons() {
    shuffleBtn.classList.toggle('is-on', shuffle);
    shuffleBtn.setAttribute('aria-pressed', shuffle ? 'true' : 'false');
    repeatBtn.classList.toggle('is-on', repeatOne);
    repeatBtn.setAttribute('aria-pressed', repeatOne ? 'true' : 'false');
  }
  shuffleBtn.addEventListener('click', function () {
    shuffle = !shuffle; store('lp-shuffle', shuffle);
    rebuildOrder(); syncModeButtons();
  });
  repeatBtn.addEventListener('click', function () {
    repeatOne = !repeatOne; store('lp-repeat-one', repeatOne);
    audio.loop = repeatOne;                              // loop the current track in place
    syncModeButtons();
  });

  if (!N) {
    titleEl.textContent = 'No tracks yet';
    [toggleBtn, prevBtn, nextBtn, shuffleBtn, repeatBtn, listBtn].forEach(function (b) { b.disabled = true; });
  } else {
    shuffle = stored('lp-shuffle');
    repeatOne = stored('lp-repeat-one');
    buildList();
    loadTrack(0);
    if (shuffle) { index = Math.floor(Math.random() * N); loadTrack(index); }
    rebuildOrder();
    syncModeButtons();
  }

  function setIcon(playing) {
    var i = toggleBtn.querySelector('i');
    i.className = playing ? 'fas fa-pause' : 'fas fa-play';
    toggleBtn.setAttribute('aria-label', playing ? 'Pause' : 'Play');
    root.classList.toggle('is-playing', playing);
    updateMarquee();
  }

  toggleBtn.addEventListener('click', function () {
    if (!N) return;
    if (audio.paused) {
      if (audio.error) step(1);                     // this file already failed to load: move on
      var p = audio.play();
      if (p && p.catch) p.catch(function () { setIcon(false); });
    } else {
      audio.pause();
    }
  });

  // Move through the play order; past the end it wraps (a fresh shuffle when shuffle is on).
  function step(dir) {
    pos += dir;
    if (pos >= N) {
      if (shuffle) {
        var last = index;
        order = shuffled(order.slice());
        if (N > 1 && order[0] === last) { order.push(order.shift()); }   // never the same song twice in a row
      }
      pos = 0;
    } else if (pos < 0) {
      pos = N - 1;
    }
    loadTrack(order[pos]);
  }

  function skip(dir) {
    if (!N) return;
    var wasPlaying = !audio.paused;
    if (dir < 0 && audio.currentTime > 3) { audio.currentTime = 0; return; }
    step(dir);
    if (wasPlaying) audio.play().catch(function () {});
  }
  prevBtn.addEventListener('click', function () { skip(-1); });
  nextBtn.addEventListener('click', function () { skip(1); });

  audio.addEventListener('play', function () { setIcon(true); startSpin(); });
  audio.addEventListener('pause', function () { setIcon(false); startSpin(); });
  audio.addEventListener('ended', function () {
    // (with repeat-one on, audio.loop restarts the song and 'ended' never fires)
    step(1);
    audio.play().catch(function () {});
  });
  // A file that can't be played (missing, empty, broken) is greyed out in the list and skipped
  // so the music keeps going; give up after every track has failed once in a row.
  var wantPlay = false, failStreak = 0;
  audio.addEventListener('play', function () { wantPlay = true; });
  toggleBtn.addEventListener('click', function () { wantPlay = audio.paused; }, true);
  audio.addEventListener('playing', function () { failStreak = 0; });
  audio.addEventListener('error', function () {
    if (!N) return;
    var item = listEl.querySelector('.lp-list-item[data-i="' + index + '"]');
    if (item) { item.classList.add('is-broken'); item.title = 'This file could not be played'; }
    titleEl.textContent = 'Cannot play: ' + prettyTitle(tracks[index]);
    if (wantPlay && ++failStreak < N) {
      setTimeout(function () { step(1); audio.play().catch(function () {}); }, 1200);
    }
  });

  // ---------- progress bar ----------
  var bar = root.querySelector('.lp-progress');
  var fill = root.querySelector('.lp-progress-fill');
  var barRaf = 0, dragging = false;

  var curEl = root.querySelector('.lp-time-cur');
  var durEl = root.querySelector('.lp-time-dur');

  // 75 -> "1:15", 3725 -> "1:02:05"
  function fmt(sec) {
    if (!(sec >= 0) || !isFinite(sec)) return '0:00';
    sec = Math.floor(sec);
    var h = Math.floor(sec / 3600), m = Math.floor(sec % 3600 / 60), s = sec % 60;
    var ss = (s < 10 ? '0' : '') + s;
    return h ? h + ':' + (m < 10 ? '0' : '') + m + ':' + ss : m + ':' + ss;
  }
  function setText(el, t) { if (el.textContent !== t) el.textContent = t; }

  function drawProgress() {
    var d = audio.duration, f = d > 0 && isFinite(d) ? Math.min(1, audio.currentTime / d) : 0;
    fill.style.transform = 'scaleX(' + f + ')';
    bar.setAttribute('aria-valuenow', Math.round(f * 100));
    bar.setAttribute('aria-valuetext', fmt(audio.currentTime) + ' / ' + fmt(d));
    setText(curEl, fmt(audio.currentTime));
    setText(durEl, fmt(d));
  }
  function barLoop() {
    drawProgress();
    barRaf = audio.paused ? 0 : requestAnimationFrame(barLoop);
  }
  function seekTo(clientX) {
    var d = audio.duration;
    if (!(d > 0) || !isFinite(d)) return;
    var r = bar.getBoundingClientRect();
    audio.currentTime = Math.max(0, Math.min(1, (clientX - r.left) / r.width)) * d;
    drawProgress();
  }
  bar.addEventListener('pointerdown', function (e) {
    if (!N) return;
    dragging = true;
    try { bar.setPointerCapture(e.pointerId); } catch (err) {}
    seekTo(e.clientX);
  });
  bar.addEventListener('pointermove', function (e) { if (dragging) seekTo(e.clientX); });
  bar.addEventListener('pointerup', function () { dragging = false; });
  bar.addEventListener('pointercancel', function () { dragging = false; });
  bar.addEventListener('keydown', function (e) {
    var d = audio.duration;
    if (!(d > 0) || !isFinite(d)) return;
    if (e.key === 'ArrowRight') audio.currentTime = Math.min(d, audio.currentTime + 5);
    else if (e.key === 'ArrowLeft') audio.currentTime = Math.max(0, audio.currentTime - 5);
    else return;
    e.preventDefault();
    drawProgress();
  });
  ['loadedmetadata', 'durationchange', 'timeupdate', 'seeked', 'emptied'].forEach(function (ev) { audio.addEventListener(ev, drawProgress); });
  audio.addEventListener('play', function () { if (!barRaf) barRaf = requestAnimationFrame(barLoop); });
  if (!N) bar.classList.add('is-disabled');

  // ---------- spectrum visualizer (LED-style bars that jump with the music) ----------
  var viz = root.querySelector('.lp-viz');
  var vctx = viz ? viz.getContext('2d') : null;
  var BARS = 14, SEGS = 9;
  var actx = null, analyser = null, freq = null, bassNode = null, gainNode = null, limiter = null;
  var levels = new Float32Array(BARS), peaks = new Float32Array(BARS), peakHold = new Float32Array(BARS);
  var mean = new Float32Array(BARS);       // slow running level per band, so beats stand out above it
  var vizRaf = 0, vizLast = 0, bandLo = [], bandHi = [];

  // Create the audio graph from a click (browsers only allow audio contexts after a user gesture).
  function ensureAudioGraph() {
    if (actx || !viz) return;
    // iOS Safari pauses Web Audio when you leave the page, which would cut the music.
    // There the <audio> element plays on its own (keeps going in the background);
    // the bars and the singer animate from a built-in rhythm instead of the real spectrum.
    if (IOS) return;
    var AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      actx = new AC();
      var srcNode = actx.createMediaElementSource(audio);
      analyser = actx.createAnalyser();
      analyser.fftSize = 2048;
      analyser.smoothingTimeConstant = 0.6;
      analyser.minDecibels = -85;
      analyser.maxDecibels = -8;           // headroom: loud masters no longer pin every bar to the top
      // source -> bass shelf -> analyser (bars see the bass change) -> volume -> speakers
      bassNode = actx.createBiquadFilter();
      bassNode.type = 'lowshelf';
      bassNode.frequency.value = 150;
      gainNode = actx.createGain();
      srcNode.connect(bassNode);
      bassNode.connect(analyser);
      analyser.connect(gainNode);
      // limiter: lets VOL go above the original level without harsh clipping
      limiter = actx.createDynamicsCompressor();
      limiter.threshold.value = -0.5; limiter.knee.value = 0; limiter.ratio.value = 20;
      limiter.attack.value = 0.002; limiter.release.value = 0.08;
      gainNode.connect(limiter);
      limiter.connect(actx.destination);
      audio.volume = 1;                    // the gain node takes over the volume
      applyMix();
      freq = new Uint8Array(analyser.frequencyBinCount);
      // log-spaced bands from 40 Hz to 14 kHz
      var nyq = actx.sampleRate / 2, n = analyser.frequencyBinCount;
      for (var b = 0; b < BARS; b++) {
        var f0 = 40 * Math.pow(14000 / 40, b / BARS), f1 = 40 * Math.pow(14000 / 40, (b + 1) / BARS);
        bandLo[b] = Math.max(1, Math.floor(f0 / nyq * n));
        bandHi[b] = Math.max(bandLo[b] + 1, Math.ceil(f1 / nyq * n));
      }
    } catch (e) { actx = null; analyser = null; }
  }
  function resumeAudio() { if (actx && actx.state === 'suspended') actx.resume().catch(function () {}); }

  function sizeViz() {
    if (!viz) return;
    var dpr = window.devicePixelRatio || 1, r = viz.getBoundingClientRect();
    var w = Math.round(r.width * dpr), h = Math.round(r.height * dpr);
    if (w && h && (viz.width !== w || viz.height !== h)) { viz.width = w; viz.height = h; }
  }

  // bottom -> top: deep red-orange to bright amber
  var SEG_COLORS = ['#b8350f', '#c63f10', '#d44b12', '#e05814', '#ea6716', '#f27a1c', '#f78f2a', '#fba53f', '#ffbd5c'];

  function drawViz() {
    if (!vctx) return;
    var W2 = viz.width, H2 = viz.height;
    vctx.clearRect(0, 0, W2, H2);
    var gapX = Math.max(2, Math.round(W2 * 0.012)), gapY = Math.max(1, Math.round(H2 * 0.035));
    var bw = (W2 - gapX * (BARS - 1)) / BARS, sh = (H2 - gapY * (SEGS - 1)) / SEGS;
    for (var b = 0; b < BARS; b++) {
      var x = b * (bw + gapX);
      var lit = Math.round(levels[b] * SEGS);
      var pk = Math.min(SEGS - 1, Math.round(peaks[b] * SEGS) - 1);
      for (var s = 0; s < SEGS; s++) {
        var y = H2 - (s + 1) * sh - s * gapY;
        vctx.fillStyle = SEG_COLORS[s];
        vctx.globalAlpha = s < lit ? 0.95 : (s === pk && pk >= lit ? 1 : 0.13);
        vctx.fillRect(x, y, bw, sh);
      }
    }
    vctx.globalAlpha = 1;
  }

  function vizFrame(ts) {
    vizRaf = 0;
    var dt = vizLast ? Math.min((ts - vizLast) / 1000, 0.1) : 0.016;
    vizLast = ts;
    var playing = !audio.paused && analyser;
    var simulated = !audio.paused && !analyser;
    if (playing) analyser.getByteFrequencyData(freq);
    var tNow = ts / 1000, beatPh = (tNow * 2) % 1;
    var active = false;
    for (var b = 0; b < BARS; b++) {
      var target = 0;
      if (playing) {
        var sum = 0;
        for (var k = bandLo[b]; k < bandHi[b]; k++) sum += freq[k];
        var v = sum / (bandHi[b] - bandLo[b]) / 255;
        v *= 0.92 + 0.5 * b / BARS;                         // lift the quieter high end a little
        mean[b] += (v - mean[b]) * Math.min(1, dt * 1.2);
        // overall loudness sets the base height, the jump above the running level makes it bounce
        target = v < 0.08 ? 0 : Math.max(0, Math.min(1, 0.2 + 0.75 * (v - 0.3) / 0.55 + 3.2 * (v - mean[b])));
      }
      if (simulated) {                                      // no audio data (iPhone): a lively stand-in
        var env = Math.exp(-beatPh * 5) * (1 - b / BARS * 0.6);
        target = Math.max(0, Math.min(1, 0.25 + 0.2 * Math.sin(tNow * (1.7 + b * 0.37) + b * 1.3) + 0.12 * Math.sin(tNow * (4.1 + b * 0.53)) + 0.5 * env));
      }
      // fast attack, slower release -> the bars "jump" on beats
      levels[b] = target > levels[b] ? target : Math.max(target, levels[b] - dt * 2.2);
      if (levels[b] >= peaks[b]) { peaks[b] = levels[b]; peakHold[b] = 0.35; }
      else if (peakHold[b] > 0) peakHold[b] -= dt;
      else peaks[b] = Math.max(0, peaks[b] - dt * 0.9);
      if (levels[b] > 0.001 || peaks[b] > 0.001) active = true;
    }
    drawViz();
    if (playing || simulated || active) vizRaf = requestAnimationFrame(vizFrame);
    else vizLast = 0;
  }
  function startViz() { if (vctx && !vizRaf) { vizLast = 0; vizRaf = requestAnimationFrame(vizFrame); } }

  if (viz) {
    sizeViz(); drawViz();
    window.addEventListener('resize', function () { sizeViz(); drawViz(); });
    // every control that can start playback is a click, so build the graph there
    [toggleBtn, prevBtn, nextBtn, listEl].forEach(function (el) {
      el.addEventListener('click', function () { ensureAudioGraph(); resumeAudio(); }, true);
    });
    audio.addEventListener('play', function () { resumeAudio(); startViz(); });
    audio.addEventListener('pause', startViz);   // let the bars fall back down
  }

  // ---------- volume / bass faders ----------
  // VOL: the middle of the fader (50) is the song's own level (0 dB).
  // Up to the top boosts it to +12 dB; down to the bottom fades it out to silence.
  var VOL_DEFAULT = 50, VOL_MAX_DB = 12, VOL_MIN_DB = -48, MIX_KEY = 'lp-mix-v2';
  var vol = VOL_DEFAULT, bassDb = 0;
  try {
    var savedMix = JSON.parse(localStorage.getItem(MIX_KEY));
    if (savedMix) { vol = Math.max(0, Math.min(100, +savedMix.vol)); bassDb = Math.max(-12, Math.min(12, +savedMix.bass)); }
    if (isNaN(vol)) vol = VOL_DEFAULT;
    if (isNaN(bassDb)) bassDb = 0;
  } catch (e) {}

  function volDb(v) {
    if (v <= 0) return -Infinity;
    return v >= 50 ? (v - 50) / 50 * VOL_MAX_DB : (50 - v) / 50 * VOL_MIN_DB;
  }
  function fmtDb(d) {
    if (d === -Infinity) return '-\u221e';
    var r = Math.round(d * 10) / 10;
    return (r > 0 ? '+' : '') + r.toFixed(1);
  }

  function applyMix() {
    var d = volDb(vol), g = d === -Infinity ? 0 : Math.pow(10, d / 20);
    if (gainNode && actx) {
      gainNode.gain.setTargetAtTime(g, actx.currentTime, 0.02);
      bassNode.gain.setTargetAtTime(bassDb, actx.currentTime, 0.02);
    } else {
      audio.volume = Math.max(0, Math.min(1, g));          // boost above 1 needs the audio graph (made on first click)
    }
  }

  function setupFader(el, min, max, step, def, get, set, show) {
    var slot = el.querySelector('.lp-fader-slot'), valEl = el.querySelector('.lp-fader-val');
    function render() {
      var v = get();
      slot.style.setProperty('--p', ((v - min) / (max - min)).toFixed(4));
      slot.setAttribute('aria-valuenow', v);
      slot.setAttribute('aria-valuetext', show(v));
      valEl.textContent = show(v);
    }
    function commit(v) {
      v = Math.round(Math.max(min, Math.min(max, v)) / step) * step;
      if (v === get()) return;
      set(v); render(); applyMix();
      try { localStorage.setItem(MIX_KEY, JSON.stringify({ vol: vol, bass: bassDb })); } catch (e) {}
    }
    function fromY(y) {
      var r = slot.getBoundingClientRect(), knob = 11;
      var p = 1 - (y - r.top - knob / 2) / (r.height - knob);
      commit(min + Math.max(0, Math.min(1, p)) * (max - min));
    }
    var dragging = false;
    slot.addEventListener('pointerdown', function (e) {
      ensureAudioGraph(); resumeAudio();
      dragging = true; slot.classList.add('is-dragging');
      try { slot.setPointerCapture(e.pointerId); } catch (err) {}
      fromY(e.clientY); e.preventDefault();
    });
    slot.addEventListener('pointermove', function (e) { if (dragging) fromY(e.clientY); });
    function end() { dragging = false; slot.classList.remove('is-dragging'); }
    slot.addEventListener('pointerup', end);
    slot.addEventListener('pointercancel', end);
    slot.addEventListener('dblclick', function () { commit(def); });   // double-click: back to default
    slot.addEventListener('keydown', function (e) {
      var k = e.key, v = get();
      if (k === 'ArrowUp' || k === 'ArrowRight') v += step;
      else if (k === 'ArrowDown' || k === 'ArrowLeft') v -= step;
      else if (k === 'PageUp') v += step * 5;
      else if (k === 'PageDown') v -= step * 5;
      else if (k === 'Home') v = min;
      else if (k === 'End') v = max;
      else return;
      e.preventDefault(); ensureAudioGraph(); resumeAudio(); commit(v);
    });
    slot.addEventListener('wheel', function (e) {
      e.preventDefault(); ensureAudioGraph(); resumeAudio();
      commit(get() + (e.deltaY < 0 ? step : -step));
    }, { passive: false });
    render();
  }

  var volFader = root.querySelector('.lp-fader[data-kind="vol"]');
  var bassFader = root.querySelector('.lp-fader[data-kind="bass"]');
  if (volFader) setupFader(volFader, 0, 100, 1, VOL_DEFAULT,
    function () { return vol; }, function (v) { vol = v; }, function (v) { return fmtDb(volDb(v)); });
  if (bassFader) setupFader(bassFader, -12, 12, 1, 0,
    function () { return bassDb; }, function (v) { bassDb = v; },
    function (v) { return fmtDb(v); });
  applyMix();

  // ---------- tonearm ----------
  // The needle lands on the outer groove when play starts, creeps inward as the song plays,
  // and swings back to its rest when paused. Geometry is in stage pixels (150 x 170.4).
  var armEl = root.querySelector('.lp-arm-swing');
  if (armEl) {
    var PIVOT_X = 172, PIVOT_Y = 22;
    var TIP_X = -11.6, TIP_Y = 110.6;                // needle tip in the arm's own coordinates
    var DISC_X = 75.04, DISC_Y = 95.1;               // record centre
    var R_START = 64, R_END = 30;                    // outer groove -> run-out groove
    var armAngle = 0, armRaf = 0, armLast = 0;

    var tipDist = function (deg) {
      var a = deg * Math.PI / 180, c = Math.cos(a), sn = Math.sin(a);
      var x = PIVOT_X + TIP_X * c - TIP_Y * sn, y = PIVOT_Y + TIP_X * sn + TIP_Y * c;
      return Math.hypot(x - DISC_X, y - DISC_Y);
    };
    // the swing angle where the distance to the centre is smallest bounds the search
    var minDeg = 0, minD = Infinity;
    for (var dg = 0; dg <= 90; dg += 0.5) { var dd = tipDist(dg); if (dd < minD) { minD = dd; minDeg = dg; } }
    var angleFor = function (r) {                    // bisection on the approaching side
      var lo = 0, hi = minDeg;
      for (var it = 0; it < 30; it++) { var mid = (lo + hi) / 2; if (tipDist(mid) > r) lo = mid; else hi = mid; }
      return (lo + hi) / 2;
    };
    var armTarget = function () {
      if (audio.paused) return 0;
      var d = audio.duration, f = d > 0 && isFinite(d) ? Math.min(1, audio.currentTime / d) : 0;
      return angleFor(R_START - (R_START - R_END) * f);
    };
    var drawArm = function () { armEl.setAttribute('transform', 'translate(' + PIVOT_X + ' ' + PIVOT_Y + ') rotate(' + armAngle.toFixed(3) + ')'); };
    var armFrame = function (ts) {
      armRaf = 0;
      var dt = armLast ? Math.min((ts - armLast) / 1000, 0.1) : 0.016;
      armLast = ts;
      var t = armTarget();
      armAngle += (t - armAngle) * Math.min(1, dt * 3.2);       // smooth swing, like a damped lift
      if (Math.abs(t - armAngle) < 0.01) armAngle = t;
      drawArm();
      if (!audio.paused || armAngle !== t) armRaf = requestAnimationFrame(armFrame);
      else armLast = 0;
    };
    var moveArm = function () { if (!armRaf) { armLast = 0; armRaf = requestAnimationFrame(armFrame); } };
    ['play', 'pause', 'seeked', 'emptied', 'loadedmetadata'].forEach(function (ev) { audio.addEventListener(ev, moveArm); });
    drawArm();
  }

  // ---------- singing buddy ----------
  // Head icon in the mode row opens a little character that floats bottom-left of the page,
  // mouths along to the vocals and bobs to the bass.
  var buddyBtn = root.querySelector('.lp-buddy-btn');
  var buddy = root.querySelector('.lp-buddy');
  if (buddyBtn && buddy) {
    document.body.appendChild(buddy);                 // out of the sidebar so it can float freely
    var bob = buddy.querySelector('.lp-buddy-bob');
    var mouthEl = buddy.querySelector('.lp-buddy-mouth');
    var notesEl = buddy.querySelector('.lp-buddy-notes');
    var buddyOpen = false, buddyRaf = 0, buddyLast = 0, buddyT = 0;
    var kick = 0, mouth = 0, bMean = 0, vMean = 0, noteIn = 0, bf = null;
    // --- rock songs: little lightning-bolt symbols shoot out of the mouth along with the notes ---
    var BOLT_SVG = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M13.5 1.5 3.5 13.8h6.6l-1.9 8.7L20.5 9.6h-6.7l2-8.1z" fill="#ffd21f" stroke="#e85d00" stroke-width="1.6" stroke-linejoin="round"/></svg>';
    var spawnBolt = function () {
      var z = document.createElement('span');
      z.className = 'lp-buddy-bolt';
      z.innerHTML = BOLT_SVG;
      // burst out to the left or right of the mouth (slightly up or down), clear of the face
      var side = Math.random() < 0.5 ? 0 : 180;
      var ang = (side + (-35 + Math.random() * 60)) * Math.PI / 180;
      var dist = 58 + Math.random() * 34;
      var size = 13 + Math.random() * 8;
      z.style.left = '51.9%'; z.style.top = '54%';
      z.style.width = z.style.height = size + 'px';
      z.style.setProperty('--dx', (Math.cos(ang) * dist).toFixed(1) + 'px');
      z.style.setProperty('--dy', (Math.sin(ang) * dist * 0.8).toFixed(1) + 'px');
      z.style.setProperty('--r0', (-25 + Math.random() * 50).toFixed(0) + 'deg');
      z.style.setProperty('--r1', (-40 + Math.random() * 80).toFixed(0) + 'deg');
      z.style.setProperty('--dur', (0.75 + Math.random() * 0.45).toFixed(2) + 's');
      z.addEventListener('animationend', function () { z.remove(); });
      notesEl.appendChild(z);
    };
    var boltIn = 0, lastKick = 0;

    var bandAvg = function (arr, f0, f1) {
      var nyq = actx.sampleRate / 2, n = arr.length;
      var lo = Math.max(1, Math.floor(f0 / nyq * n)), hi = Math.max(lo + 1, Math.ceil(f1 / nyq * n)), sum = 0;
      for (var k = lo; k < hi; k++) sum += arr[k];
      return sum / (hi - lo) / 255;
    };
    var spawnNote = function () {
      var n = document.createElement('span');
      n.className = 'lp-buddy-note';
      n.textContent = Math.random() < 0.5 ? '♪' : '♫';
      // warm "orange rainbow": each note gets its own red→orange→yellow (now and then pink) gradient
      var h = Math.random() < 0.15 ? 330 + Math.random() * 20 : Math.random() * 48;
      n.style.setProperty('--n1', 'hsl(' + h.toFixed(0) + ', 100%, 56%)');
      n.style.setProperty('--n2', 'hsl(' + ((h + 22 + Math.random() * 18) % 360).toFixed(0) + ', 100%, 55%)');
      n.style.left = (50 + Math.random() * 14) + '%';
      n.style.top = (34 + Math.random() * 12) + '%';
      n.style.setProperty('--dx', (10 + Math.random() * 26) + 'px');
      n.addEventListener('animationend', function () { n.remove(); });
      notesEl.appendChild(n);
    };
    var buddyFrame = function (ts) {
      buddyRaf = 0;
      if (!buddyOpen) return;
      var dt = buddyLast ? Math.min((ts - buddyLast) / 1000, 0.1) : 0.016;
      buddyLast = ts; buddyT += dt;
      var playing = !audio.paused, targetMouth = 0;
      if (playing && analyser) {
        if (!bf) bf = new Uint8Array(analyser.frequencyBinCount);
        analyser.getByteFrequencyData(bf);
        var bass = bandAvg(bf, 40, 160), vocal = bandAvg(bf, 300, 3000);
        bMean += (bass - bMean) * Math.min(1, dt * 1.5);
        vMean += (vocal - vMean) * Math.min(1, dt * 1.2);
        if (bass - bMean > 0.045 && kick < 0.35) kick = 1;                 // a beat: hop
        // open on each vocal swell above the running level, snap shut in between (뻐끔뻐끔)
        targetMouth = vocal < 0.12 ? 0 : Math.max(0, Math.min(1, (vocal - vMean - 0.004) * 11));
      } else if (playing) {                                               // no analyser yet: fake it
        var beat = (buddyT * 2) % 1;
        if (beat < dt * 2 && kick < 0.35) kick = 1;
        targetMouth = Math.max(0, Math.sin(buddyT * 11)) * 0.9;
      }
      kick = Math.max(0, kick - dt * 3.6);
      mouth += (targetMouth - mouth) * Math.min(1, dt * (targetMouth > mouth ? 30 : 22));
      var hop = Math.sin(kick * Math.PI / 2);                             // ease the hop
      var sway = playing ? Math.sin(buddyT * 2.4) * 3 : 0;
      var breathe = playing ? 0 : Math.sin(buddyT * 1.6) * 0.8;
      bob.style.transform = 'translateY(' + (-hop * 7 + breathe).toFixed(2) + 'px) rotate(' + sway.toFixed(2) + 'deg) scale(' + (1 + hop * 0.025).toFixed(3) + ',' + (1 - hop * 0.02 + kick * 0.0).toFixed(3) + ')';
      // shut: the face image has a closed mouth; open: the drawing's pink triangle mouth drops open over it
      mouthEl.style.opacity = mouth > 0.08 ? 1 : 0;
      mouthEl.style.transform = 'scale(' + (0.85 + mouth * 0.3).toFixed(3) + ',' + (0.55 + mouth * 0.95).toFixed(3) + ')';
      if (playing && mouth > 0.3) { noteIn -= dt; if (noteIn <= 0) { spawnNote(); noteIn = (N && tracks[index].rock ? 0.3 : 0.55) + Math.random() * 0.4; } }
      // rock songs: fire ⚡ out of the mouth while singing, a burst on each beat
      var rockNow = playing && N && tracks[index].rock;
      if (rockNow && mouth > 0.22) {
        boltIn -= dt;
        if (boltIn <= 0) { spawnBolt(); boltIn = 0.11 + Math.random() * 0.14; }
        if (kick > 0.95 && lastKick <= 0.95) { spawnBolt(); spawnBolt(); if (Math.random() < 0.5) spawnBolt(); }
      }
      lastKick = kick;
      buddyRaf = requestAnimationFrame(buddyFrame);
    };
    var setBuddy = function (open, remember) {
      buddyOpen = open;
      buddy.hidden = !open;
      buddyBtn.classList.toggle('is-on', open);
      buddyBtn.setAttribute('aria-pressed', open ? 'true' : 'false');
      if (remember) { try { localStorage.setItem('lp-buddy', open ? '1' : '0'); } catch (e) {} }
      if (open) requestAnimationFrame(layoutBuddy);
      if (open && !buddyRaf) { buddyLast = 0; buddyRaf = requestAnimationFrame(buddyFrame); }
    };
    buddyBtn.addEventListener('click', function () { ensureAudioGraph(); resumeAudio(); setBuddy(!buddyOpen, true); });
    buddy.querySelector('.lp-buddy-close').addEventListener('click', function (e) { e.stopPropagation(); setBuddy(false, true); });

    // Keep it pinned to the part of the page you can actually see. On iPhone the Safari bars
    // grow/shrink and pinch-zoom moves the visible area, so place it against visualViewport
    // and re-place on every scroll/resize. Drag it anywhere; the spot is remembered.
    var vv = window.visualViewport || null;
    var pos = null;                                    // {x, y} inside the visible area; null = bottom-left
    try { pos = JSON.parse(localStorage.getItem('lp-buddy-pos')) || null; } catch (e) {}
    var view = function () {
      return vv ? { x: vv.offsetLeft, y: vv.offsetTop, w: vv.width, h: vv.height }
                : { x: 0, y: 0, w: window.innerWidth, h: window.innerHeight };
    };
    var layoutBuddy = function () {
      if (buddy.hidden) return;
      var v = view(), w = buddy.offsetWidth, h = buddy.offsetHeight;
      var x = pos ? pos.x : 18, y = pos ? pos.y : v.h - h - 14;
      x = Math.max(0, Math.min(v.w - w, x)); y = Math.max(0, Math.min(v.h - h, y));
      buddy.style.left = (v.x + x) + 'px'; buddy.style.top = (v.y + y) + 'px'; buddy.style.bottom = 'auto';
    };
    var layoutQueued = false;
    var queueLayout = function () {
      if (layoutQueued) return;
      layoutQueued = true;
      requestAnimationFrame(function () { layoutQueued = false; layoutBuddy(); });
    };
    if (vv) { vv.addEventListener('scroll', queueLayout); vv.addEventListener('resize', queueLayout); }
    window.addEventListener('scroll', queueLayout, { passive: true });
    window.addEventListener('resize', queueLayout);
    window.addEventListener('orientationchange', function () { setTimeout(layoutBuddy, 300); });

    var drag = null;
    buddy.addEventListener('pointerdown', function (e) {
      if (e.target.closest('.lp-buddy-close')) return;
      var r = buddy.getBoundingClientRect();
      drag = { dx: e.clientX - r.left, dy: e.clientY - r.top };
      buddy.classList.add('is-dragging');
      try { buddy.setPointerCapture(e.pointerId); } catch (err) {}
      e.preventDefault();
    });
    buddy.addEventListener('pointermove', function (e) {
      if (!drag) return;
      var v = view();
      pos = { x: e.clientX - drag.dx - v.x, y: e.clientY - drag.dy - v.y };
      layoutBuddy();
    });
    var endDrag = function () {
      if (!drag) return;
      drag = null; buddy.classList.remove('is-dragging');
      try { localStorage.setItem('lp-buddy-pos', JSON.stringify(pos)); } catch (e) {}
    };
    buddy.addEventListener('pointerup', endDrag);
    buddy.addEventListener('pointercancel', endDrag);

    if (stored('lp-buddy')) setBuddy(true, false);
  }

  // ---------- lock screen / Control Center / media keys ----------
  // Shows the song on the iPhone lock screen and macOS Now Playing, and lets the
  // play/pause, next and previous buttons there (and keyboard media keys) drive this player.
  if ('mediaSession' in navigator && N) {
    var ms = navigator.mediaSession;
    var artwork = [{ src: base + 'artwork-512.jpg', sizes: '512x512', type: 'image/jpeg' }];
    var splitTitle = function (t) {
      var m = t.match(/^(.*?)\s*-\s*([^-]+)$/);
      if (!m) return { title: t, artist: '' };
      var artist = m[2].trim();
      return { title: m[1].trim(), artist: artist.charAt(0).toUpperCase() + artist.slice(1) };
    };
    var updateMeta = function () {
      var p = splitTitle(prettyTitle(tracks[index]));
      try { ms.metadata = new MediaMetadata({ title: p.title, artist: p.artist, album: 'v2llain.github.io', artwork: artwork }); } catch (e) {}
    };
    var updatePos = function () {
      var d = audio.duration;
      if (!(d > 0) || !isFinite(d) || !ms.setPositionState) return;
      try { ms.setPositionState({ duration: d, playbackRate: audio.playbackRate || 1, position: Math.min(d, audio.currentTime || 0) }); } catch (e) {}
    };
    var act = function (name, fn) { try { ms.setActionHandler(name, fn); } catch (e) {} };
    act('play', function () { audio.play().catch(function () {}); });
    act('pause', function () { audio.pause(); });
    act('previoustrack', function () { if (audio.currentTime > 3) audio.currentTime = 0; else step(-1); audio.play().catch(function () {}); });
    act('nexttrack', function () { step(1); audio.play().catch(function () {}); });
    act('seekto', function (d) { if (d && d.seekTime != null) { audio.currentTime = d.seekTime; updatePos(); } });
    act('seekbackward', function (d) { audio.currentTime = Math.max(0, audio.currentTime - ((d && d.seekOffset) || 10)); updatePos(); });
    act('seekforward', function (d) { audio.currentTime = Math.min(audio.duration || 0, audio.currentTime + ((d && d.seekOffset) || 10)); updatePos(); });
    audio.addEventListener('loadstart', updateMeta);
    audio.addEventListener('loadedmetadata', updatePos);
    audio.addEventListener('seeked', updatePos);
    audio.addEventListener('play', function () { ms.playbackState = 'playing'; updateMeta(); updatePos(); });
    audio.addEventListener('pause', function () { ms.playbackState = 'paused'; updatePos(); });
    updateMeta();
  }

  // ---------- keep playing across page reloads ----------
  // Remembers the track, position and whether it was playing. After a reload it picks up at the
  // same spot. Browsers usually refuse to start sound on their own after a page load, so if that
  // happens the song resumes on the visitor's first click or key press anywhere on the page.
  var STATE_KEY = 'lp-state', RESUME_WINDOW_MS = 30 * 60 * 1000;
  var lastSave = 0, restoring = false;

  function saveState(force) {
    if (!N || restoring) return;
    var now = Date.now();
    if (!force && now - lastSave < 1000) return;
    lastSave = now;
    try {
      localStorage.setItem(STATE_KEY, JSON.stringify({
        src: tracks[index].src, t: audio.currentTime || 0, playing: !audio.paused, at: now
      }));
    } catch (e) {}
  }
  audio.addEventListener('timeupdate', function () { saveState(false); });
  ['play', 'pause', 'seeked', 'loadstart'].forEach(function (ev) { audio.addEventListener(ev, function () { saveState(true); }); });
  window.addEventListener('pagehide', function () { saveState(true); });
  document.addEventListener('visibilitychange', function () { if (document.hidden) saveState(true); });

  function restoreState() {
    var st = null;
    try { st = JSON.parse(localStorage.getItem(STATE_KEY)); } catch (e) {}
    if (!st || !st.src) return;
    var i = -1;
    for (var k = 0; k < N; k++) if (tracks[k].src === st.src) { i = k; break; }
    if (i < 0) return;                                   // that song was removed from /music/
    restoring = true;
    if (i !== index) loadTrack(i);
    rebuildOrder();
    var seekDone = false;
    function seek() {
      if (seekDone) return;
      seekDone = true;
      if (st.t > 0 && isFinite(audio.duration) && st.t < audio.duration - 1) audio.currentTime = st.t;
      restoring = false;
    }
    if (audio.readyState >= 1) seek(); else audio.addEventListener('loadedmetadata', seek, { once: true });
    audio.load();
    if (!(st.playing && Date.now() - (st.at || 0) < RESUME_WINDOW_MS)) return;

    function waitForGesture() {
      root.classList.add('is-resume-pending');
      function go(e) {
        document.removeEventListener('pointerdown', go, true);
        document.removeEventListener('keydown', go, true);
        root.classList.remove('is-resume-pending');
        if (e && e.target && e.target.closest && e.target.closest('.lp-btn, .lp-list, .lp-progress')) return; // a player control handles itself
        ensureAudioGraph(); resumeAudio();
        audio.play().catch(function () {});
      }
      document.addEventListener('pointerdown', go, true);
      document.addEventListener('keydown', go, true);
    }
    var p = audio.play();
    if (p && p.catch) p.catch(waitForGesture);
  }

  if (N) restoreState();
  // If the browser did allow the song to resume by itself, hook up the bars on the first click.
  function wakeViz() {
    document.removeEventListener('pointerdown', wakeViz, true);
    if (!audio.paused) { ensureAudioGraph(); resumeAudio(); startViz(); }
  }
  document.addEventListener('pointerdown', wakeViz, true);

  // ---------- disc rendering ----------
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var discCanvas = document.createElement('canvas');
  discCanvas.width = discCanvas.height = DS;
  var dctx = discCanvas.getContext('2d', { willReadFrequently: true });
  var caseImg, discImg, light, glare, mask, ready = false;
  var angle = 0, speed = 0, lastTs = 0, rafId = 0;

  function loadImg(name) {
    return new Promise(function (res, rej) {
      var im = new Image();
      im.onload = function () { res(im); };
      im.onerror = rej;
      im.src = base + name;
    });
  }

  function pixels(im) {
    var c = document.createElement('canvas');
    c.width = DS; c.height = DS;
    var x = c.getContext('2d');
    x.drawImage(im, 0, 0, DS, DS);
    return x.getImageData(0, 0, DS, DS).data;
  }

  function render() {
    dctx.setTransform(1, 0, 0, 1, 0, 0);
    dctx.clearRect(0, 0, DS, DS);
    dctx.translate(DS / 2, DS / 2);
    dctx.rotate(angle);
    dctx.drawImage(discImg, -DS / 2, -DS / 2, DS, DS);
    dctx.setTransform(1, 0, 0, 1, 0, 0);
    var id = dctx.getImageData(0, 0, DS, DS), p = id.data, n = p.length;
    for (var i = 0; i < n; i += 4) {
      p[i]     = p[i]     * light[i]     + glare[i];
      p[i + 1] = p[i + 1] * light[i + 1] + glare[i + 1];
      p[i + 2] = p[i + 2] * light[i + 2] + glare[i + 2];
      p[i + 3] = mask[i];
    }
    dctx.putImageData(id, 0, 0);
    ctx.clearRect(0, 0, W, H);
    ctx.drawImage(discCanvas, DX, DY);
    ctx.drawImage(caseImg, 0, 0, W, H);
  }

  function frame(ts) {
    rafId = 0;
    var dt = lastTs ? Math.min((ts - lastTs) / 1000, 0.1) : 0;
    lastTs = ts;
    var target = audio.paused || reduceMotion ? 0 : 1;
    var stepS = dt / SPIN_EASE;
    speed = target > speed ? Math.min(target, speed + stepS) : Math.max(target, speed - stepS);
    angle = (angle + speed * dt * 2 * Math.PI / SECONDS_PER_TURN) % (2 * Math.PI);
    render();
    if (speed > 0 || target > 0) rafId = requestAnimationFrame(frame);
    else lastTs = 0;
  }

  function startSpin() {
    if (ready && !rafId) { lastTs = 0; rafId = requestAnimationFrame(frame); }
  }

  Promise.all(['case.webp', 'disc.webp', 'light.png', 'glare.png', 'mask.png'].map(loadImg))
    .then(function (ims) {
      caseImg = ims[0]; discImg = ims[1];
      var l = pixels(ims[2]), g = pixels(ims[3]), m = pixels(ims[4]);
      light = new Float32Array(l.length);
      glare = new Float32Array(g.length);
      for (var i = 0; i < l.length; i++) { light[i] = l[i] / 127.5; glare[i] = g[i] - 128; }
      mask = new Uint8ClampedArray(m.length);
      for (var j = 0; j < m.length; j += 4) mask[j] = m[j];
      ready = true;
      render();
      root.classList.add('is-ready');
      if (!audio.paused) startSpin();
    })
    .catch(function () { root.classList.add('is-fallback'); });
})();
